ui.Image recordPressGlowProfile() {
  final recorder = ui.PictureRecorder();
  final canvas = ui.Canvas(recorder);
  final paint = ui.Paint()..isAntiAlias = true;
  for (var i = 0; i < pressGlowProfileRed.length; i++) {
    paint.color = ui.Color.from(
      alpha: 1,
      red: pressGlowProfileRed[i],
      green: 0,
      blue: 0,
      colorSpace: ui.ColorSpace.extendedSRGB,
    );
    canvas.drawRect(ui.Rect.fromLTWH(i.toDouble(), 0, 1, 1), paint);
  }
  final picture = recorder.endRecording();
  final image = picture.toImageSync(64, 1);
  picture.dispose();
  return image;
}
